"""Low-overhead SHA-256 solver.

hashlib's one-shot operation avoids constructing and finalizing the higher-level
cryptography Hash context used by the reference implementation.
"""
import hashlib

_sha256 = hashlib.sha256


class Solver:
    def solve(self, problem, **kwargs):
        return {"digest": _sha256(problem["plaintext"]).digest()}

